/* https://antfu.me/posts/animated-svg-logo */
<style scoped>
.the-logo {
  --signature-length: 2000px;
  height: 24px;
  width: full;
}

.the-path {
  stroke: #070707;
  stroke-dashoffset: 1px;
  stroke-dasharray: var(--signature-length) 0;
  animation: grow 8s ease-out forwards infinite;
  transform-origin: center;
  animation-delay: 0s;
}
.dark .the-path {
  stroke: #fdfdfd;
}

@media (prefers-reduced-motion) {
  path {
    animation: none !important;
    stroke-dasharray: unset !important;
  }
}
@media print {
  path {
    animation: none !important;
    stroke-dasharray: unset !important;
  }
}
@keyframes grow {
  0% {
    stroke-dashoffset: 1px;
    stroke-dasharray: 0 var(--signature-length);
    opacity: 0;
  }
  5% {
    opacity: 1;
  }
  45% {
    stroke-dasharray: var(--signature-length) 0;
  }
  /* Moving back */
  65% {
    stroke-dasharray: var(--signature-length) 0;
  }
  95%,
  to {
    stroke-dasharray: 0 var(--signature-length);
  }
}
</style>
